<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,shallowRef,nextTick} from 'vue';
import bundledConfig from '../../content/game-config.json' with {type:'json'};
import {EVENTS} from './game/incidents';
import {CAMPAIGNS,campaignIntel} from './game/campaigns';
import LanGame from './components/LanGame.vue';
const lanOpen=ref(new URLSearchParams(location.search).has('lan'));
import CampaignMap from './components/CampaignMap.vue';
import ChangeLog from './components/ChangeLog.vue';
import changelog from '../../content/changelog.json';
import CampaignVictory from './components/CampaignVictory.vue';
import EnemyGuide from './components/EnemyGuide.vue';
import Onboarding from './components/Onboarding.vue';
import BackgroundPicker from './components/BackgroundPicker.vue';
import {normalizeBackground} from './game/render/backgrounds';
import TacticalPanel from './components/TacticalPanel.vue';
import {Engine} from './game/engine';import {Renderer} from './game/render/canvas';import {AudioSystem} from './game/render/audio';
import type {Config,World,Difficulty} from './game/types';import {useSession} from './stores/session';import {api,localGet,localPut} from './api/client';import {SaveQueue,validateSnapshot} from './game/persistence';
const portable=import.meta.env.VITE_PORTABLE==='true';
const ui=useSession(),config=shallowRef<Config>(),engine=shallowRef<Engine>(),canvas=ref<HTMLCanvasElement>(),version=ref(0),hover=ref(-999),hoverLayer=ref(0),ready=ref(false),saved=shallowRef<World|null>(null),serverSave=shallowRef<World|null>(null),error=ref(''),busy=ref(false),small=ref(false),duplicate=ref(false),runs=ref<any[]>([]),best=ref(0),dev=import.meta.env.DEV,devType=ref('grunt'),perf=ref({fps:60,ms:0});
const chosenCampaign=ref<number|null>(null),campaignSaving=ref(false);let campaignRecorded='';const chosenTest=ref(false);const chosenDifficulty=ref<Difficulty>('easy');const difficultyNames={easy:'简单',normal:'普通',hard:'困难'};
const squadSlot=ref(0);const selection=ref<number[]>([]);const group=computed(()=>{void version.value;return engine.value?.upgradeSelection(selection.value,0);});
const dramatic=computed(()=>{void version.value;const e=engine.value;if(!e||e.cinematic)return null;if(e.s.event)return {title:EVENTS[e.s.event.kind].title,detail:'距抵达 '+Math.ceil(e.s.event.remaining)+' 秒 · '+EVENTS[e.s.event.kind].detail};const worm=e.s.enemies.find(a=>a.type==='sandworm'&&a.state==='burrow'&&a.hp>0);if(worm)return {title:'裂地沙虫 / 建筑下方巨震',detail:'距钻出 '+Math.ceil(worm.timer)+' 秒 · 红色通道内建筑将被摧毁'};if(e.s.campaign?.stage===4&&e.s.campaign.timelineVersion===3&&e.s.campaign.spawned===1&&e.time>=590&&e.time<600)return {title:'最后的攻势 / 母舰即将抵达',detail:'距决战 '+Math.ceil(600-e.time)+' 秒 · 全体坚守，守住最后的航道'};if(e.s.bossWarning>=0)return {title:'巨型敌军信号 / BOSS 接近',detail:'距抵达 '+Math.ceil(e.s.bossWarning)+' 秒 · 调整阵型、检查防空'};return e.alert.until>e.time?e.alert:null;});
let sceneCheckpoint='';let renderer:Renderer|undefined,raf=0,last=0,acc=0,lastSave=0,ended='',channel:BroadcastChannel|undefined,frames=0,measure=0,measureAt=0,lastAlarm=0;const audio=new AudioSystem();
const saves=new SaveQueue(m=>ui.saveStatus=m,()=>{if(engine.value)engine.value.paused=true;ui.modal='conflict';void refreshServer();},r=>{if(engine.value)engine.value.s.revision=r;});
const state=computed(()=>{void version.value;return engine.value?{...engine.value.s}:undefined;}),selected=computed(()=>{void version.value;const b=engine.value?.s.buildings.find(b=>b.id===ui.selectedId);return b?{...b}:undefined;}),stats=computed(()=>selected.value&&engine.value?.stats(selected.value));
const economy=computed(()=>{void version.value;return engine.value?.economy();});
const minePreview=computed(()=>{void version.value;return engine.value&&ui.selectedKind==='mine'&&hover.value>=engine.value.minColumn&&hover.value<engine.value.config.world.columns?engine.value.minePreview(hover.value):null;});
const rate=(n:number)=>n.toFixed(1);
const clock=(s:number)=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
const phase=computed(()=>{void version.value;const e=engine.value;if(e?.chapter)return e.campaignRelief?'整备窗口 · 10:00 海空决战':e.cinematic?'沉船苏醒 · 战斗暂停':e.s.campaign?.timelineVersion===3&&e.s.campaign.spawned===2?'击落母舰 · 等待残骸坠毁':e.nextCampaignBossAt!==null?'战役推进 · 下一批统领 '+clock(Math.max(0,e.nextCampaignBossAt-e.time)):'决战进行中 · 击败全部统领';const t=(state.value?.tick||0)/60%60;return t<35?`强袭将在 ${Math.ceil(35-t)} 秒后到来`:t<50?`强袭进行中 · 剩余 ${Math.ceil(50-t)} 秒`:`缓和阶段 · 强袭倒计时 ${Math.ceil(95-t)} 秒`;});
const warning=computed(()=>{if(!state.value||!config.value)return '';if(dramatic.value||engine.value?.cinematic)return '';const t=state.value.tick/60;const n=state.value.campaign?undefined:Object.values(config.value.enemies).filter(p=>!p.boss&&p.unlock>t&&p.unlock-t<=15).sort((a,b)=>a.unlock-b.unlock)[0];return n?`${n.name}将在 ${Math.ceil(n.unlock-t)} 秒后加入刷怪池`:state.value.coreHp<=900?'核心生命危急 · 请立即维修':engine.value?.message||'';});
async function refreshServer(){try{const {data,revision}=await api<{revision:number;snapshot:World}>('/save');serverSave.value=data?.snapshot||null;return data?.revision??revision;}catch{return null;}}
async function boot(){error.value='';try{const {data}=await api<Config>('/config');if(data.configVersion!==1||!data.buildings.wall||!data.enemies.carrier)throw Error('配置不兼容');config.value=data;await localPut('config',data);ui.saveStatus=portable?'离线版 · 存档在此浏览器':'存档服务已连接';}catch{config.value=await localGet<Config>('config')||undefined;ui.saveStatus='服务离线 · 使用浏览器缓存';}if(config.value)config.value={...config.value,enemies:{...bundledConfig.enemies,...config.value.enemies},schedule:{...bundledConfig.schedule,...config.value.schedule}};if(!config.value){error.value='未连接本地服务。请先启动 backend，再点击重试连接。';return;}
 try{const {data}=await api<typeof ui.settings>('/settings');ui.settings={...ui.settings,...data,background:normalizeBackground(data.background)};}catch{const s=await localGet<typeof ui.settings>('settings');if(s)ui.settings={...ui.settings,...s,background:normalizeBackground(s.background)};}
 const local=await localGet<World>('save'),revision=await refreshServer();if(revision!==null)saves.revision=revision;else saves.revision=local?.revision||0;
 saved.value=serverSave.value;if(local?.alive){const different=serverSave.value&&local.runId!==serverSave.value.runId;const staleBase=revision!==null&&local.revision!==revision&&local.tick>(serverSave.value?.tick??-1);if(different||staleBase){saved.value=local;saves.blocked=true;ui.modal='conflict';}else saved.value=local.tick>=(serverSave.value?.tick??0)?local:serverSave.value;}
 ui.settings.campaignCleared=Math.max(ui.settings.campaignCleared||0,(await localGet<typeof ui.settings>('settings'))?.campaignCleared||0);if((await localGet<typeof ui.settings>('settings'))?.tutorialSeen)ui.settings.tutorialSeen=true;ready.value=true;if(!ui.settings.tutorialSeen&&!ui.modal)ui.modal='onboarding';await submitPending();}
async function saveSettings(){await localPut('settings',{...ui.settings});try{await api('/settings','PUT',{...ui.settings});}catch{ui.saveStatus='设置仅保存在浏览器';}}
function openModal(name:string){if(engine.value?.cinematic)return;stopFire();if(engine.value){engine.value.paused=true;engine.value.demolition=null;}ui.modal=name;audio.unlock();}
function changeDifficulty(ev:Event){if(engine.value?.chapter)return;const d=(ev.target as HTMLSelectElement).value as Difficulty;chosenDifficulty.value=d;if(engine.value){engine.value.setDifficulty(d);version.value++;void save();}}
function closeModal(){ui.modal='';}
function finishOnboarding(){ui.settings.tutorialSeen=true;void saveSettings();ui.modal='';}
async function restartGame(){const e=engine.value;if(!e||busy.value||e.cinematic)return;chosenCampaign.value=e.s.campaign?.stage??null;chosenDifficulty.value=e.s.difficulty??'easy';chosenTest.value=!!e.s.testMode;saved.value=e.snapshot();error.value='';audio.unlock();await startGame();}
async function newGame(){chosenCampaign.value=null;audio.unlock();if(saved.value){ui.modal='overwrite';return;}await startGame();}
async function beginCampaign(stage:number,advance=false){if(stage>ui.settings.campaignCleared||stage<0||stage>4)return;chosenCampaign.value=stage;if(saved.value&&!advance){ui.modal='overwrite';return;}await startGame();}
async function recordCampaign(){const e=engine.value,m=e?.s.campaign;if(!e||!m?.won||campaignSaving.value||busy.value)return;campaignSaving.value=true;campaignRecorded=e.s.runId;try{await save();ui.settings.campaignCleared=Math.max(ui.settings.campaignCleared,m.stage+1);await saveSettings();}finally{campaignSaving.value=false;}}
function campaignMenu(){localExit();ui.modal='campaign';}
async function startGame(){if(!config.value||busy.value)return;busy.value=true;try{if(saved.value)await localPut('backup',saved.value);const e=new Engine(config.value,20260905,crypto.randomUUID());e.setDifficulty(chosenDifficulty.value);e.s.testMode=chosenTest.value;if(chosenCampaign.value!==null)e.startCampaign(chosenCampaign.value);e.s.revision=saves.revision;const ok=await saves.save(e.snapshot());if(!ok){error.value='新游戏尚未替换原存档，请恢复服务后重试。';return;}saved.value=e.snapshot();engine.value=e;campaignRecorded='';ended='';lastSave=0;ui.selectedKind='';ui.selectedId=0;selection.value=[];ui.page='game';ui.modal=e.chapter?'mission':ui.settings.tutorialSeen?'':'onboarding';e.paused=!!e.chapter||!ui.settings.tutorialSeen;await nextTick();renderer=new Renderer(canvas.value!);}finally{busy.value=false;}}
async function continueGame(){audio.unlock();if(!config.value||!saved.value)return;try{const e=new Engine(config.value,1,'',validateSnapshot(saved.value,config.value));e.s.revision=saves.revision;engine.value=e;if(e.cinematic)e.paused=false;chosenTest.value=!!e.s.testMode;chosenCampaign.value=e.s.campaign?.stage??null;campaignRecorded='';selection.value=[];ui.selectedId=0;ui.page='game';ui.modal='';ui.selectedKind='';lastSave=e.s.tick;await nextTick();renderer=new Renderer(canvas.value!);}catch(e){error.value=(e as Error).message;}}
async function save(){if(!engine.value?.s.alive)return false;saved.value=engine.value.snapshot();return saves.save(saved.value);}
async function saveExit(){busy.value=true;try{if(await save()){ui.page='menu';ui.modal='';engine.value=undefined;renderer=undefined;}else if(!saves.blocked)ui.modal='offline';}finally{busy.value=false;}}
function localExit(){ui.page='menu';ui.modal='';engine.value=undefined;renderer=undefined;}
function togglePause(){const e=engine.value;if(e&&!e.cinematic&&e.s.alive&&!ui.modal&&!small.value&&!duplicate.value){e.paused=!e.paused;e.aim.fire=false;e.demolition=null;version.value++;audio.unlock();}}
function selectKind(k:string){if(engine.value?.running&&!ui.modal&&engine.value.buildingUnlocked(k)){engine.value.relocating=0;ui.selectedKind=ui.selectedKind===k?'':k;ui.selectedId=0;selection.value=[];engine.value.control(0);audio.unlock();}}
function pointer(ev:PointerEvent){if(!renderer)return;const p=renderer.point(ev.clientX,ev.clientY);hover.value=Math.floor(p.x);hoverLayer.value=Math.floor(p.y);if(engine.value)Object.assign(engine.value.aim,p);}
function drop(ev:PointerEvent){audio.unlock();const e=engine.value;if(!e?.running||ui.modal||ev.button!==0||!renderer)return;const p=renderer.point(ev.clientX,ev.clientY);if(e.relocating){const reason=e.relocationError(e.relocating,Math.floor(p.x),Math.floor(p.y));if(reason){e.notify(reason);return;}e.command({type:'relocate',id:e.relocating,column:Math.floor(p.x),layer:Math.floor(p.y)});e.relocating=0;return;}const clicked=e.s.buildings.find(b=>Math.abs(b.x-p.x)<=.5&&Math.abs(b.y-p.y)<=.5&&b.hp>0);if(!ui.selectedKind&&clicked){if(ev.shiftKey){e.control(0);selection.value=selection.value.includes(clicked.id)?selection.value.filter(x=>x!==clicked.id):[...selection.value,clicked.id];}else{selection.value=[clicked.id];e.control(clicked.id);}ui.selectedId=clicked.id;return;}if(e.controlled){Object.assign(e.aim,p,{fire:true});(ev.currentTarget as HTMLElement).setPointerCapture(ev.pointerId);return;}if(ui.selectedKind)e.command({type:'drop',kind:ui.selectedKind,column:Math.floor(p.x),...(ui.selectedKind==='bridge'?{layer:Math.floor(p.y)}:{})});else {const id=e.s.buildings.find(b=>Math.abs(b.x-p.x)<=.5&&Math.abs(b.y-p.y)<=.5)?.id||0;if(ev.shiftKey&&id){selection.value=selection.value.includes(id)?selection.value.filter(x=>x!==id):[...selection.value,id];}else selection.value=id?[id]:[];ui.selectedId=id;}}
function stopFire(){if(engine.value)engine.value.aim.fire=false;}
function control(){if(engine.value&&selected.value){engine.value.control(engine.value.controlled===selected.value.id?0:selected.value.id);selection.value=[selected.value.id];}}
function selectSame(ev:MouseEvent){const e=engine.value;if(!e?.s.alive||ui.modal||ui.selectedKind||e.relocating||!renderer)return;const p=renderer.point(ev.clientX,ev.clientY),b=e.s.buildings.find(b=>b.hp>0&&Math.abs(b.x-p.x)<=.5&&Math.abs(b.y-p.y)<=.5);if(!b||!['ballista','mortar','cannon','sniper','anti_air','frost'].includes(b.type))return;selection.value=e.s.buildings.filter(a=>a.hp>0&&a.type===b.type).map(a=>a.id);ui.selectedId=b.id;e.controlMany(selection.value);version.value++;}
function switchFront(side:'left'|'right'){const e=engine.value;if(!e||side==='left'&&!e.leftOpen)return;cancel();e.viewSide=side;hover.value=-999;version.value++;}
function takeAll(){const e=engine.value;if(!e)return;cancel();e.controlMany(e.s.buildings.map(b=>b.id));selection.value=[...e.controlledIds];ui.selectedId=e.controlled;version.value++;}
function squadSave(append=false){const e=engine.value;if(!e)return;e.assignSquad(squadSlot.value,selection.value,append);version.value++;void save();}
function squadSelect(slot:number){const e=engine.value;if(!e)return;cancel();squadSlot.value=slot;selection.value=e.squadMembers(slot);ui.selectedId=selection.value[0]??0;e.controlMany(selection.value);version.value++;}
function squadClear(){engine.value?.assignSquad(squadSlot.value,[]);version.value++;void save();}
function bulk(branch:number){engine.value?.command({type:'upgradeMany',ids:[...selection.value],branch});}
function beginLift(){if(!engine.value||!selected.value)return;cancel();engine.value.relocating=selected.value.id;}
function cancel(){if(engine.value)engine.value.relocating=0;ui.selectedKind='';engine.value?.control(0);stopFire();}
function upgrade(branch:number){if(selected.value)engine.value?.command({type:'upgrade',id:selected.value.id,branch});}
function demolish(ev:PointerEvent){if(!selected.value||!engine.value?.running)return;(ev.currentTarget as HTMLElement).setPointerCapture(ev.pointerId);engine.value.command({type:'demolish',id:selected.value.id});}
function stopDemolish(){if(engine.value){engine.value.demolition=null;engine.value.s.commands=engine.value.s.commands.filter(c=>c.type!=='demolish');}}
function choose(id:string){engine.value?.choose(id);version.value++;void save();}
function blur(){stopFire();if(ui.page==='game'&&engine.value?.s.alive){engine.value.paused=true;stopDemolish();version.value++;void save();}}
function resize(){small.value=innerWidth<1280||innerHeight<720;if(small.value)blur();}
function keyboard(ev:KeyboardEvent){if(engine.value?.cinematic){ev.preventDefault();return;}if(ui.page!=='game'||ui.modal||state.value?.candidates.length||(ev.target as HTMLElement)?.matches('input,select,textarea'))return;if(ev.ctrlKey&&ev.code==='KeyA'){ev.preventDefault();takeAll();return;}if(/^F[1-5]$/.test(ev.code)){ev.preventDefault();const slot=Number(ev.code.slice(1))-1;squadSlot.value=slot;if(ev.ctrlKey)squadSave(!ev.shiftKey);else squadSelect(slot);return;}if(ev.code==='Escape'){ev.preventDefault();if(ui.selectedKind||engine.value?.controlled||engine.value?.relocating)cancel();else togglePause();}else if(ev.code==='KeyD'&&!ev.ctrlKey&&!ev.metaKey){ev.preventDefault();selectKind('decoy');}else if(ev.code==='KeyE'){control();}else if(ev.code==='Space'){ev.preventDefault();togglePause();}else if('1234567890-[]'.includes(ev.key)&&ev.key.length===1&&config.value)selectKind(Object.keys(config.value.buildings)['1234567890-[]'.indexOf(ev.key)]);}
async function history(){openModal('history');try{const {data}=await api<{items:any[];bestScore:number}>('/runs');runs.value=data.items;best.value=data.bestScore;await localPut('runs',data);}catch{const data=await localGet<{items:any[];bestScore:number}>('runs');runs.value=data?.items||[];best.value=data?.bestScore||0;error.value='战绩服务离线，显示浏览器缓存';}}
async function submitPending(){const pending=await localGet<any[]>('pendingRuns')||[];const left=[];for(const r of pending){try{await api('/runs','POST',r);}catch{left.push(r);}}await localPut('pendingRuns',left);if(left.length)ui.saveStatus='结算待提交 · 已保留本地记录';}
async function finish(){const s=engine.value!.s;if(ended===s.runId)return;ended=s.runId;ui.selectedKind='';saved.value=null;await saves.busy;await localPut('save',null);const pending=await localGet<any[]>('pendingRuns')||[];pending.push({runId:s.runId,durationTicks:s.tick,kills:s.kills,bossKills:s.bossKills,maxThreat:s.maxThreat});await localPut('pendingRuns',pending);await submitPending();const revision=await refreshServer();if(revision!==null)saves.revision=revision;}
async function resolveConflict(local:boolean){const r=await refreshServer();if(r===null){error.value='服务仍不可用，无法安全解决冲突';return;}if(local){if(!saved.value)return;await localPut('serverBackup',serverSave.value);saves.revision=r;saves.blocked=false;if(await saves.save(saved.value))ui.modal='';}else{await saves.busy;saves.blocked=false;saves.revision=r;await localPut('backup',saved.value);saved.value=serverSave.value;await localPut('save',saved.value);engine.value=undefined;ui.page='menu';ui.modal='';}}
async function exportSave(){const value=saved.value||await localGet('backup');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.download='warwall-save.json';a.click();URL.revokeObjectURL(a.href);}
function frame(now:number){raf=requestAnimationFrame(frame);const dt=Math.min(.25,(now-last)/1000||0);last=now;const e=engine.value;if(e){const begin=performance.now();if((e.running||e.cinematic&&!e.paused)&&!ui.modal&&!small.value&&!duplicate.value){acc+=dt;let n=0;while(acc>=1/60&&n<8){e.step();acc-=1/60;n++;}if(n===8)acc=0;}else acc=0;measure+=performance.now()-begin;frames++;if(now-measureAt>=1000){perf.value={fps:Math.round(frames*1000/(now-measureAt)),ms:measure/Math.max(frames,1)};frames=0;measure=0;measureAt=now;}version.value++;renderer?.draw(e,hover.value,ui.selectedKind,ui.selectedId,ui.settings.reducedMotion,hoverLayer.value,selection.value,e.chapter?.background??ui.settings.background);audio.music(ui.settings.musicVolume,e.running&&!ui.modal);audio.storm(ui.settings.musicVolume,!!e.s.campaign?.storm&&e.running&&!ui.modal);const sounds=e.sounds.splice(0);if(sounds.length)audio.play(sounds.includes('hullCollision')?'hullCollision':sounds.includes('oceanSurge')?'oceanSurge':sounds.includes('thunder')?'thunder':sounds.includes('failure')?'failure':sounds.includes('alarm')?'alarm':sounds.includes('explosion')?'explosion':sounds[sounds.length-1],ui.settings.sfxVolume);if(e.s.coreHp<=900&&e.time-lastAlarm>5&&e.running){lastAlarm=e.time;audio.play('alarm',ui.settings.sfxVolume);}if(e.s.campaign?.timelineVersion===3&&e.s.campaign.revealFrame!=null){if(e.s.campaign.revealFrame>=-360&&!ui.settings.falseEndingAchievement){ui.settings.falseEndingAchievement=true;void saveSettings();}const key=e.s.runId+':'+Math.floor(e.s.campaign.revealFrame/120);if(key!==sceneCheckpoint){sceneCheckpoint=key;void save();}}if(e.s.alive&&e.s.tick-lastSave>=900){lastSave=e.s.tick;void save();}if(e.s.campaign?.won&&campaignRecorded!==e.s.runId)void recordCampaign();if(!e.s.alive&&ended!==e.s.runId)void finish();}else {audio.music(0,false);audio.storm(0,false);}}
function debugSpawn(){const e=engine.value;if(e){if(e.config.enemies[devType.value].boss&&e.s.enemies.some(a=>e.config.enemies[a.type].boss))return;e.spawn(devType.value);version.value++;}}
function debugPerk(){if(engine.value){engine.value.s.nextPerk=engine.value.time;engine.value.paused=false;}}
onMounted(()=>{resize();window.addEventListener('resize',resize);window.addEventListener('blur',blur);window.addEventListener('keydown',keyboard);document.addEventListener('visibilitychange',visibility);channel=new BroadcastChannel('warwall-active');channel.onmessage=ev=>{if(ev.data==='hello')channel?.postMessage('occupied');if(ev.data==='occupied'){duplicate.value=true;blur();}};channel.postMessage('hello');raf=requestAnimationFrame(frame);void boot().catch(e=>error.value=String(e));});
function visibility(){if(document.hidden)blur();}
onUnmounted(()=>{cancelAnimationFrame(raf);window.removeEventListener('resize',resize);window.removeEventListener('blur',blur);window.removeEventListener('keydown',keyboard);document.removeEventListener('visibilitychange',visibility);channel?.close();audio.close();});
</script>

<template>
 <LanGame v-if="lanOpen" :config="(config||bundledConfig) as Config" @close="lanOpen=false" @achievement="ui.settings.falseEndingAchievement=true;saveSettings()" />
 <main v-else :class="['app',ui.page,{'reduced-motion':ui.settings.reducedMotion,'expanded-layout':ui.settings.layout!=='classic'}]">
  <header class="topbar"><a class="brand" @click="ui.page==='game'?openModal('pause'):null"><span class="brand-mark">▥</span> 战墙 <small>WARWALL</small></a><div class="top-center"><span class="live-dot"></span> {{ui.page==='game'?'防御指挥终端 / SECTOR 01':'单机无限生存 / ENDLESS DEFENSE'}}</div><button class="text-button" @click="openModal('settings')">⚙ 设置</button></header>
  <template v-if="ui.page==='menu'"><button class="primary" @click="ui.modal='';lanOpen=true">局域网联机 · 合作作战</button>
   <section class="menu-content"><div class="menu-copy"><div class="eyebrow"><span></span> 最后防线 · 01</div><h1>筑起高墙。<br>守住<span>最后的光。</span></h1><p class="intro">从天而降的堡垒，无休无止的进攻。<br>建造、发展、重构防线，让核心再多跳动一秒。</p><label class="difficulty-choice">战局难度 <select v-model="chosenDifficulty" aria-label="新局难度"><option v-for="(name,id) in difficultyNames" :value="id">{{name}}</option></select><small>所有模式与难度：玩家子弹、箭矢和炮弹穿透全部友方建筑。</small></label><label class="check"><input v-model="chosenTest" type="checkbox">测试模式：10 分钟后开启左侧战场</label><div class="menu-actions"><button class="primary" :disabled="!ready||busy" @click="newGame">{{busy?'正在创建…':'建立新防线'}} <span>↗</span></button><button :disabled="!ready||!saved" @click="continueGame">继续防守 <span>{{saved?clock(saved.tick/60):'暂无存档'}}</span></button></div><button class="campaign-entry" :disabled="!config" @click="openModal('campaign')">故事战役 · 黎明计划 <span>{{ui.settings.campaignCleared}} / 5 已通关 ↗</span></button><div class="menu-links"><button class="changelog-entry" @click="openModal('changelog')">更新日志 · v{{changelog.version}} ↗</button><button :disabled="!config" @click="openModal('bestiary')">怪物图鉴 ↗</button><button @click="history">历史战绩 ↗</button><button @click="openModal('tutorial')">操作说明 ↗</button></div><div class="status"><span class="live-dot"></span>{{ui.saveStatus}}</div><p v-if="error" class="error">{{error}} <button @click="boot">重试连接</button><button v-if="saved" @click="exportSave">导出存档</button></p></div>
   <div class="fortress-art" aria-label="工业堡垒插画"><div class="art-grid"></div><div class="art-title">防线档案 <span>WW—001</span></div><div class="moon"></div><div class="far-city"><i v-for="n in 14" :key="n" :style="{height:(25+n*17%90)+'px'}"></i></div><div class="tower t1"><div class="gun"></div><b>➶</b><b>▥</b><b>▥</b></div><div class="tower t2"><div class="gun"></div><b>◒</b><b>◎</b><b>▥</b><b>▥</b><b>▥</b></div><div class="tower t3"><b>⌁</b><b>▥</b></div><div class="reactor"><span>✧</span><small>CORE / ONLINE</small></div><div class="ground"></div><div class="art-tag"><span class="live-dot"></span> 核心在线 <strong>100%</strong></div><div class="art-bottom">重力搭建 / 持续生存 <span>36 × 16</span></div></div>
   </section><footer><span>每一次坍塌，都是重建的开始。</span><span>作者：沈奕安 <i>•</i> V1.0 <i>•</i> 本地运行，无需账号</span></footer>
  </template>
  <template v-else-if="state && engine && config">
   <section class="hud"><div class="hud-item gold"><small>可用金币</small><strong>◇ {{state.gold}} <em>G</em></strong><span v-if="economy" class="income-total">总产能 {{rate(economy.total)}} G / 分{{economy.multiplier>1?' · 产能加成 ×'+economy.multiplier:''}}</span></div><div class="hud-item core"><small>核心完整度 <span>{{Math.ceil(state.coreHp/config.world.coreHp*100)}}%</span></small><strong>{{Math.ceil(state.coreHp)}} <em>/ {{config.world.coreHp}}</em></strong><div class="meter"><i :style="{width:state.coreHp/config.world.coreHp*100+'%'}"></i></div></div><div class="hud-item"><small>生存时间</small><strong>{{clock(state.tick/60)}}</strong></div><div class="hud-item"><small>{{difficultyNames[state.difficulty||'easy']}} · 威胁等级</small><strong><em>LV.</em> {{state.maxThreat.toString().padStart(2,'0')}}</strong></div><div class="assault"><span :class="{'hot':state.tick/60%60>=35&&state.tick/60%60<50}">◈ {{phase}}</span><small>击杀 {{state.kills}} · Boss {{state.bossKills}}</small></div><button class="pause-button" @click="togglePause">{{engine.paused?'▶ 继续':'Ⅱ 暂停'}} <kbd>Space</kbd></button><button class="icon-button" title="游戏菜单" aria-label="游戏菜单" @click="openModal('pause')">☰</button></section>
   <div v-if="engine.chapter" class="mission-strip"><b>战役 {{state.campaign!.stage+1}} · {{engine.chapter.title}}</b><span>统领击破 {{state.bossKills}} / {{engine.chapter.bosses.length}} · {{engine.cinematic?'沉船苏醒 · 操作锁定':state.campaign!.timelineVersion===3&&state.campaign!.spawned===2?'击落母舰并撑过坠落':engine.nextCampaignBossAt!==null?clock(Math.max(0,engine.nextCampaignBossAt-engine.time))+' 后下一批统领登场':'击败全部统领完成任务'}}</span><span v-if="engine.campaignRelief" class="relief-note">整备窗口 · 刷怪 35% · 10:00 决战</span><button @click="openModal('mission')">作战提示</button></div><section class="squad-bar" aria-label="部队指挥"><b>部队</b><button @click="takeAll">全部接管 · Ctrl+A</button><button v-for="i in 5" :class="{active:squadSlot===i-1}" :aria-label="'选择部队 '+i" @click="squadSelect(i-1)">F{{i}} · {{engine.squadMembers(i-1).length}} 座</button><select v-model.number="squadSlot" aria-label="编入目标部队"><option v-for="i in 5" :value="i-1">部队 {{i}}</option></select><button :disabled="!selection.length" @click="squadSave(true)">加入部队 {{squadSlot+1}}</button><button :disabled="!selection.length" @click="squadSave(false)">替换编队</button><button :disabled="!engine.squadMembers(squadSlot).length" @click="squadClear">清空</button><small>Shift 多选 · Ctrl+F 追加 · Ctrl+Shift+F 替换</small></section>
   <div v-if="state.testMode" class="front-bar"><b>双线测试</b><button :class="{active:engine.viewSide==='right'}" @click="switchFront('right')">右侧战场 · {{state.enemies.filter(a=>a.side!=='left').length}} 敌人</button><button :disabled="!engine.leftOpen" :class="{active:engine.viewSide==='left'}" @click="switchFront('left')">左侧战场 · {{engine.leftOpen?state.enemies.filter(a=>a.side==='left').length+' 敌人':clock(Math.max(0,600-engine.time))+' 后开启'}}</button><small>{{engine.leftOpen?'两线持续战斗 · 共用金币与核心 · 切换视角不暂停':'10:00 开放，10:20 开始左侧进攻'}}</small></div><TacticalPanel :engine="engine" :tick="version" /><section class="battle-layout"><div class="battle"><div v-for="lord in state.enemies.filter(a=>a.type==='leviathan'&&a.hp>0)" :key="lord.id" class="lord-health" role="progressbar" aria-label="深渊潮汐领主生命" :aria-valuenow="Math.ceil(lord.hp)" :aria-valuemax="lord.maxHp" aria-valuemin="0"><span>深渊潮汐领主 · {{Math.ceil(lord.hp)}} / {{lord.maxHp}}</span><i :style="{width:(100*lord.hp/lord.maxHp)+'%'}"></i></div><div class="battle-label"><span>{{engine.chapter?.map||(engine.viewSide==='left'?'左翼战区':'右翼战区')}} <i>/</i> {{engine.chapter?.title||'灰烬边境'}}</span><span>{{ui.selectedKind?'投放模式 · 右键取消':'指挥模式 · 点击建筑查看详情'}}</span></div><canvas ref="canvas" @pointermove="pointer" @pointerleave="hover=-999" @pointerdown="drop" @dblclick="selectSame" @pointerup="stopFire" @pointercancel="stopFire" @lostpointercapture="stopFire" @contextmenu.prevent="cancel"></canvas><div v-if="engine.cinematic" class="reveal-caption" role="status"><template v-if="(state.campaign!.revealFrame??0)<-360"><small>敌舰信号消失</small><h2>海面归于寂静。</h2><p>正在确认战场……</p></template><template v-else-if="(state.campaign!.revealFrame??0)<180"><small>成就达成</small><h2>结束了？</h2><p>最后的残骸，沉入了海面。</p></template><template v-else><small>沉没港湾 / 未知巨型信号</small><h2>{{(state.campaign!.revealFrame??0)<420?'沉船……在动。':'它从未沉睡。'}}</h2><p>沉船苏醒 · 战斗与经济暂停 · 操作锁定</p></template></div><div v-if="dramatic" class="incident-banner" role="status"><small>紧急战术通告 / WARNING</small><strong>{{dramatic.title}}</strong><span>{{dramatic.detail}}</span></div><div v-if="engine.controlled" class="manual-hint">手动操控 {{engine.controlledIds.length||1}} 座 · 按住左键瞄准开火 · 右键退出</div><div v-if="warning" class="warning">△ {{warning}}</div><div v-if="engine.paused&&!engine.cinematic&&!ui.modal&&!state.candidates.length&&state.alive" class="paused-label"><strong>模拟已暂停</strong><span>按 Space 或点击右上角继续</span></div><div class="battle-caption"><span>↓ 普通建筑投放 · 桥梁水平铺设 · 无坠落损伤</span><span v-if="dev">{{perf.fps}} FPS / {{perf.ms.toFixed(2)}} ms</span><span v-else>固定步长 60 Hz</span></div></div>
    <aside class="details"><details v-if="economy" class="economy-panel"><summary>经济明细 · {{rate(economy.total)}} G/分</summary><dl><dt>矿场原产能（含强化）</dt><dd>{{rate(economy.raw)}}</dd><dt>递减损失</dt><dd>−{{rate(economy.loss)}}</dd><dt>矿场实际 / {{economy.count}} 座</dt><dd>{{rate(economy.actual)}}</dd><dt>固定补贴</dt><dd>+{{rate(economy.passive)}}</dd><dt>经济总产能</dt><dd>{{rate(economy.total)}}</dd></dl><small>仅统计已落稳矿场；不含击杀、回收与事件奖励。按周期发放，暂停时不生产。</small></details><div v-if="ui.selectedKind==='mine'" class="economy-panel"><b>新矿建造预览</b><template v-if="minePreview"><p>落点：第 {{hover+1}} 列 · 落稳后</p><dl><dt>原产能（含强化）</dt><dd>{{rate(minePreview.raw/minePreview.interval*60)}} G/分</dd><dt>本矿递减损失</dt><dd>−{{rate(minePreview.loss/minePreview.interval*60)}} G/分</dd><dt>已有矿场损失</dt><dd>0 G/分</dd><dt>总产能净增加</dt><dd>+{{rate(minePreview.rate)}} G/分</dd></dl></template><p v-else>将鼠标移到战场目标列，查看堆叠损失和实际增产。</p><small>超过前 6 座与同列堆叠仅降低后建矿场收益。建造条件仍以落点提示为准。</small></div><div v-if="selected?.type==='decoy'" class="economy-panel"><b>诱饵投影 · 限造 1 座</b><p>每 {{engine.stats(selected).interval}} 秒投影 {{engine.stats(selected).production}} 秒，诱导投影周围 {{engine.stats(selected).range}} 格内的普通敌人。Boss、空中堡垒和孵化兽不受影响。</p><small>{{state.projection?.owner===selected.id?'投影剩余 '+state.projection.remaining.toFixed(1)+' 秒':'下次投影 '+selected.cooldown.toFixed(1)+' 秒'}}</small></div><div class="section-label">建筑情报 <span>INSPECT</span></div><div v-if="selection.length>1 && group" class="bulk-upgrade"><b>已选择 {{selection.length}} 座 · 可升级 {{group.buildings.length}} 座</b><p>按各建筑对应分支统一升级 · 合计 {{group.cost}} G</p><button v-for="i in [0,1]" :disabled="!engine.running||!group.buildings.length||state.gold<group.cost" @click="bulk(i)">统一升级方向 {{i+1}}</button><small v-for="b in group.buildings" :key="b.id">{{config.buildings[b.type].name}}：{{config.buildings[b.type].branches.map(p=>p.name).join(' / ')}}<br></small></div><template v-if="selected && stats"><button v-if="selected.type!=='crane'&&engine.s.buildings.some(b=>b.type==='crane'&&b.hp>0)" :disabled="!engine.running||!selected.settled||!engine.craneFor(selected)" @click="beginLift">吊装移位 · 35 G</button><p v-if="engine.relocating" class="lift-hint">点击目标空格直接移位，可放入桥梁下方；右键取消。落点需要稳定支撑，且在吊装站范围内。</p><button v-if="['ballista','mortar','cannon','sniper','anti_air','frost'].includes(selected.type)" :disabled="!selected.settled" @click="control">{{engine.controlled===selected.id?'退出操控':'操控此塔'}} · E</button><div class="detail-icon">{{stats.icon}}</div><h2>{{stats.name}}</h2><p>{{stats.description}}</p><div class="detail-hp">结构生命 <strong>{{Math.ceil(selected.hp)}} / {{Math.ceil(stats.hp)}}</strong></div><div class="meter"><i :style="{width:selected.hp/stats.hp*100+'%'}"></i></div><dl><dt>当前状态</dt><dd>{{selected.settled?'已落稳 · 工作中':'下落中 · 功能冻结'}}</dd><template v-if="selected.type==='mine'"><dt>基础原产能</dt><dd>{{stats.production}} G / {{stats.interval}} 秒</dd><dt>强化后原产能</dt><dd>{{rate(engine.mineOutput(selected).raw)}} G / 周期</dd><dt>递减损失</dt><dd>−{{rate(engine.mineOutput(selected).loss)}} G / 周期</dd><dt>实际产出</dt><dd>{{selected.settled?engine.mineIncome(selected):0}} G / {{stats.interval}} 秒</dd><dt>产能序号 / 同列序号</dt><dd>{{engine.mineOutput(selected).rank}} / {{engine.mineOutput(selected).stack}}</dd></template><dt>累计投入</dt><dd>{{selected.spent}} G</dd><dt>有效范围</dt><dd>{{stats.range}} 格</dd></dl><div class="section-label">分支升级 <span>{{selected.branch>=0?'已完成':'二选一'}}</span></div><template v-if="selected.branch<0"><button v-for="(branch,i) in config.buildings[selected.type].branches" :key="i" class="upgrade" :disabled="!engine.running||!selected.settled||state.gold<stats.upgradeCost" @click="upgrade(i)"><b>{{branch.name}} <span>{{stats.upgradeCost}} G</span></b><small>{{Object.entries(branch).filter(([k])=>k!=='name').map(([k,v])=>({hp:'生命',damage:'伤害',interval:'间隔',range:'范围',production:selected?.type==='decoy'?'持续时间（秒）':'产量',radius:'爆炸半径',slow:'减速',slowDuration:'减速持续',boost:'增幅',thorns:'反伤'}[k]||k)+' '+v).join(' · ')}}</small></button></template><p v-else>已选择：{{stats.name}}</p><button class="demolish" :disabled="!engine.running||!selected.settled" @pointerdown="demolish" @pointerup="stopDemolish" @pointercancel="stopDemolish" @lostpointercapture="stopDemolish"><i :style="{width:(engine.demolition?.id===selected.id?Math.min(100,engine.demolition.elapsed/.3*100):0)+'%'}"></i><span>按住 0.3 秒拆除 <b>+{{engine.refund(selected)}} G</b></span></button><small class="muted">回收金额随当前生命变化；失去全部支撑的桥段及上层建筑会重新下落。</small></template><template v-else><div class="empty-icon">⌖</div><h3>{{ui.selectedKind?config.buildings[ui.selectedKind].name:'选择你的防线'}}</h3><p>{{ui.selectedKind?config.buildings[ui.selectedKind].description:'点击建筑查看状态；Shift + 点击多选统一升级。点击防御塔直接接管，双击选择全部同类塔；F1—F5 选择部队一起瞄准。'}}</p><div class="tip"><b>指挥官提示</b><p>城墙在前，火力居高。<br>矿场提供长期收入，防空塔守护天空。</p></div><div class="sector-stats"><span>建筑数量</span><strong>{{state.buildings.length.toString().padStart(2,'0')}}</strong><span>敌军信号</span><strong>{{state.enemies.length.toString().padStart(2,'0')}}</strong></div></template></aside></section>
   <section class="build-tray"><div class="tray-heading"><span>建造序列 <b v-if="engine.deploymentSpeed>1">· 吊装速度 ×2</b> <small>选择建筑后点击目标列 · 横向滚动查看新建筑</small></span><span>{{state.dropCooldown>0?'吊装就绪倒计时 '+state.dropCooldown.toFixed(1)+'s':'● 吊装系统就绪'}}</span></div><div class="building-cards"><button v-for="(p,k,i) in config.buildings" :key="k" :class="['building-card',{active:ui.selectedKind===k,unaffordable:state.gold<p.cost,locked:!engine.buildingUnlocked(String(k))}]" :disabled="!engine.running||!!ui.modal||!engine.buildingUnlocked(String(k))||engine.buildingCount(String(k))>=engine.buildingLimit(String(k))" :title="!engine.buildingUnlocked(String(k))?'后续战役解锁':p.limit?'最多 '+engine.buildingLimit(String(k))+' 座（含下落中）':''" @click="selectKind(String(k))"><kbd>{{k==='decoy'?'D':'1234567890-[]'[i]}}</kbd><span class="building-icon">{{p.icon}}</span><div><strong>{{p.name}}{{engine.buildingUnlocked(String(k))?'':' 🔒'}}</strong><small>{{p.cost}} <em>G</em><span v-if="p.limit"> · {{engine.buildingCount(String(k))}}/{{engine.buildingLimit(String(k))}}</span></small></div></button></div></section>
   <div class="game-footer"><span>{{ui.saveStatus}}</span><span><kbd>1—9 / 0 / -</kbd> 选建筑 <i>·</i> <kbd>右键</kbd> 取消 <i>·</i> <kbd>Space</kbd> 暂停</span></div>
   <details v-if="dev" class="dev-tools"><summary>开发测试</summary><select v-model="devType"><option v-for="(p,k) in config.enemies" :value="k">{{p.name}}</option></select><button @click="debugSpawn">生成敌人</button><button @click="debugPerk">触发强化</button><button @click="engine.s.coreHp=0;engine.s.alive=false">测试结算</button></details>
  </template>
  <div v-if="ui.modal || state?.campaign?.won || state?.candidates.length || state&&!state.alive || small || duplicate" class="overlay">
   <section class="dialog" :class="{'wide':ui.modal==='history'||ui.modal==='bestiary'||state?.candidates.length}">
    <template v-if="small"><div class="eyebrow">调整显示窗口</div><h2>需要更宽阔的战场</h2><p>请将浏览器窗口调整至至少 1280 × 720，或缩小浏览器缩放比例。模拟已暂停。</p></template>
    <template v-else-if="duplicate"><h2>已有指挥终端在线</h2><p>检测到另一个游戏标签页。请关闭本页，返回已有页面继续，避免存档冲突。</p></template>
    <template v-else-if="ui.modal==='conflict'"><h2>选择要保留的防线</h2><p>检测到不同存档或版本冲突，模拟已暂停。选择前将保留被替换存档的浏览器备份。</p><button @click="resolveConflict(true)">保留浏览器存档 · {{clock((saved?.tick||0)/60)}}</button><button @click="resolveConflict(false)">采用服务器存档 · {{clock((serverSave?.tick||0)/60)}}</button><button @click="exportSave">导出浏览器 JSON</button><p class="error">{{error}}</p></template>
    <template v-else-if="state?.campaign?.won && !ui.modal"><CampaignVictory :stage="state.campaign.stage" :ticks="state.tick" :kills="state.kills" :boss-kills="state.bossKills" :total-bosses="engine?.chapter?.bosses.length" :saving="campaignSaving" @menu="campaignMenu" @next="beginCampaign(state.campaign.stage+1,true)" @retry="beginCampaign(state.campaign.stage,true)" /></template><template v-else-if="state && !state.alive && ui.page==='game'"><div class="eyebrow">防线失守 / SIGNAL LOST</div><h2>核心熄灭，意志不灭。</h2><p>你的堡垒坚持了 {{clock(state.tick/60)}}。下一次，筑得更坚固。</p><div class="result-score">{{Math.floor(state.tick/60)*10+state.kills*5+state.bossKills*500}}<small>本局得分</small></div><div class="result-grid"><span>击杀<strong>{{state.kills}}</strong></span><span>Boss 击杀<strong>{{state.bossKills}}</strong></span><span>最高威胁<strong>{{state.maxThreat}}</strong></span></div><button class="primary" @click="startGame">再次部署 ↗</button><button @click="localExit">返回主菜单</button><small>{{ui.saveStatus}}</small><button v-if="ui.saveStatus.includes('待提交')" @click="submitPending">重试提交战绩</button></template>
    <template v-else-if="state?.candidates.length && !ui.modal"><div class="eyebrow">战地补给 / FIELD UPGRADE</div><h2>让防线更进一步。</h2><p>选择一项强化，立即作用于本局防线。模拟已暂停。</p><div class="perk-cards"><button v-for="id in state.candidates" :key="id" @click="choose(id)"><span>✧</span><h3>{{config?.perks[id]?.name||'应急补给'}}</h3><p>{{config?.perks[id]?.description||'+100 金币'}}</p><small>当前 {{state.perks[id]||0}} 层 · 点击获得 →</small></button></div></template>
    <template v-else-if="ui.modal==='restart'"><h2>重新开始当前战局？</h2><p>{{engine?.chapter?'将从头重玩当前战役关卡。':'将按当前难度和模式重新建设防线。'}}本局金币、建筑和战斗进度将重置；已解锁的战役、成就及设置保留。原战局会保留浏览器备份。</p><button class="primary" :disabled="busy||!engine" @click="restartGame">确认重新开始</button><button :disabled="busy" @click="ui.modal='settings'">取消，返回设置</button><p class="error">{{error}}</p></template><template v-else-if="ui.modal==='overwrite'"><h2>建立新的防线？</h2><p>已有 {{clock((saved?.tick||0)/60)}} 的进行中存档。新游戏成功保存后将替换它，原存档会保留浏览器备份。</p><button class="primary" :disabled="busy" @click="startGame">确认新游戏</button><button @click="closeModal">保留原防线</button><p class="error">{{error}}</p></template>
    <template v-else-if="ui.modal==='pause'"><div class="eyebrow">指挥暂停</div><h2>防线等待你的命令。</h2><button class="primary" @click="closeModal();togglePause()">继续防守</button><button :disabled="busy" @click="saveExit">{{busy?'正在保存…':'保存并返回主菜单'}}</button><button @click="openModal('settings')">设置</button><button @click="openModal('tutorial')">操作说明</button><small>{{ui.saveStatus}}</small></template>
    <template v-else-if="ui.modal==='offline'"><h2>本地副本已保留</h2><p>{{ui.saveStatus}}。当前进度仅保存在此浏览器，尚未写入后端数据库。</p><button class="primary" @click="localExit">保留浏览器存档并返回</button><button @click="saveExit">重试保存</button><button @click="closeModal">留在战场</button></template>
    <template v-else-if="ui.modal==='bestiary' && config"><EnemyGuide :unlocked="ui.settings.falseEndingAchievement" :config="config" @close="closeModal" /></template>
    <template v-else-if="ui.modal==='campaign'"><CampaignMap :unlocked="ui.settings.falseEndingAchievement" :cleared="ui.settings.campaignCleared" :busy="busy" @start="beginCampaign" @close="closeModal" /></template><template v-else-if="ui.modal==='mission' && engine?.chapter"><div class="eyebrow">战役 {{state!.campaign!.stage+1}} / {{engine.chapter.map}}</div><h2>{{engine.chapter.title}}</h2><p>{{campaignIntel(engine.chapter,ui.settings.falseEndingAchievement).story}}</p><p class="mission-tip">{{campaignIntel(engine.chapter,ui.settings.falseEndingAchievement).hint}}</p><p>目标：击败 {{campaignIntel(engine.chapter,ui.settings.falseEndingAchievement).bosses.map(k=>config!.enemies[k].name).join(' ＋ ')}}。本关可用 {{engine.chapter.buildings.length}} 类建筑。</p><button class="primary" @click="closeModal();engine.paused=false">开始 / 继续战役</button></template><template v-else-if="ui.modal==='settings'"><div class="eyebrow">系统设置</div><h2 class="settings-title">你的指挥环境</h2><button :disabled="!engine||busy||engine.cinematic" @click="error='';ui.modal='restart'">重新开始</button><small v-if="!engine" class="muted">进入战局后可重新开始。</small><p v-if="engine?.chapter">战役使用本关固定地图与难度。通关可解锁新设施和下一张地图。</p><label class="difficulty-choice">战场布局<select v-model="ui.settings.layout" aria-label="战场布局" @change="saveSettings"><option value="expanded">宽阔战场（推荐）</option><option value="classic">经典布局（原版）</option></select><small>宽阔布局压缩工具栏与留白，保留完整战场、建筑情报和操作按钮。</small></label><BackgroundPicker v-model="ui.settings.background" @update:model-value="saveSettings" /><p v-if="ui.settings.falseEndingAchievement" class="achievement-record">✦ 已获得成就：结束了？</p><button @click="openModal('onboarding')">新手引导 · 重新体验</button><label class="difficulty-choice">{{engine?'当前战局难度':'新局难度'}}<select :value="engine?.s.difficulty||chosenDifficulty" aria-label="战局难度" :disabled="!!engine?.chapter" @change="changeDifficulty"><option v-for="(name,id) in difficultyNames" :value="id">{{name}}</option></select><small>普通：敌人生命 ×1.45 / 伤害 ×1.25 / 数量速率 ×1.35。困难：×2.1 / ×1.6 / ×1.7。切换立即生效，已发射弹体保留原伤害。狙击塔上限：所有难度均为 20 座；切换后超限的已有塔保留。怪物与 Boss 每分钟持续增强，第 10 分钟后增长加快。</small><strong>所有模式与难度：玩家子弹、箭矢、炮弹及冰霜攻击均可穿过城墙和其他友方建筑。敌方及反弹弹体不享受穿透。</strong></label><label class="setting">背景音景 <span>{{Math.round(ui.settings.musicVolume*100)}}%</span><input v-model.number="ui.settings.musicVolume" type="range" min="0" max="1" step=".05" @input="audio.unlock();saveSettings()"></label><label class="setting">战斗音效 <span>{{Math.round(ui.settings.sfxVolume*100)}}%</span><input v-model.number="ui.settings.sfxVolume" type="range" min="0" max="1" step=".05" @input="audio.unlock();saveSettings()"></label><button @click="audio.unlock();audio.play('explosion',ui.settings.sfxVolume)">试听战斗音效</button><label class="check"><input v-model="ui.settings.reducedMotion" type="checkbox" @change="saveSettings"> 减少动态效果</label><button class="primary" @click="closeModal">完成</button></template>
    <template v-else-if="ui.modal==='onboarding'"><Onboarding @finish="finishOnboarding" /></template><template v-else-if="ui.modal==='tutorial'"><button @click="openModal('onboarding')">重新体验新手引导</button><div class="eyebrow">指挥官手册 / QUICK START</div><h2>一格一格，筑起生机。</h2><ol class="instructions"><li><b>选择与投放</b><p>点击下方建筑，或按 1—9 / 0 / -；点击战场目标列。普通建筑从顶部落下；桥梁点击指定高度直接铺设，可水平延伸并承载上层，失去全部支撑会坠落。虚线框显示落点，投放冷却 1.2 秒。</p></li><li><b>搭建与经济</b><p>地面城墙阻挡敌人行进；所有模式下玩家攻击均可穿过城墙和其他友方建筑。矿场每 10 秒产金币；敌人从右侧持续进攻，及时布置防空。</p></li><li><b>升级与回收</b><p>右键取消投放后，点击建筑升级；Shift + 点击多选，侧栏显示总费用并统一选择分支。点击防御塔直接操控，F1—F5 接管编队，指向敌人并按住左键开火，右键退出；仍受射程、冷却和遮挡限制。按住拆除 0.3 秒回收部分费用，上层将坠落；坠落不伤友军。</p></li><li><b>暂停与保存</b><p>Space 暂停；切换窗口自动暂停。每 15 秒自动保存，也可从菜单保存退出。再次继续需手动恢复。</p></li></ol><button class="primary" @click="closeModal">明白了，开始指挥 →</button></template>
    <template v-else-if="ui.modal==='changelog'"><ChangeLog :unlocked="ui.settings.falseEndingAchievement" @close="closeModal" /></template>
    <template v-else-if="ui.modal==='history'"><div class="eyebrow">防御档案 / RECENT RUNS</div><h2>每一道防线，都有记录。</h2><p>本地最高分 <strong class="gold">{{best}}</strong></p><div class="history-table"><table><thead><tr><th>结束时间</th><th>生存</th><th>击杀 / Boss</th><th>威胁</th><th>得分</th></tr></thead><tbody><tr v-for="r in runs" :key="r.runId"><td>{{new Date(r.endedAt).toLocaleString()}}</td><td>{{clock(r.survivalSeconds)}}</td><td>{{r.kills}} / {{r.bossKills}}</td><td>{{r.maxThreat}}</td><td>{{r.score}}</td></tr></tbody></table><p v-if="!runs.length">暂无战绩。你的第一道防线，正等待建立。</p></div><button class="primary" @click="closeModal">返回</button></template>
   </section>
  </div>
 </main>
 <div v-if="engine?.cinematic" class="cinematic-input-lock" aria-label="过场播放中，操作已锁定" @contextmenu.prevent><button v-if="engine.paused" class="primary" @click="audio.unlock();engine.paused=false">继续观看过场</button></div>
</template>
